CREATE OR REPLACE PROCEDURE sp(
    para_Location    VARCHAR2,
    para_Fate        VARCHAR2,
    para_Speed_knots NUMBER,
    para_Ship_ID     NUMBER
) AS
    CURSOR c_mission IS
        SELECT *
          FROM mission
         WHERE Location > para_Location
           FOR UPDATE;
    r_mission mission%ROWTYPE;
    v_avg_speed NUMBER;
BEGIN
    OPEN c_mission;
    LOOP
        FETCH c_mission INTO r_mission;
        EXIT WHEN c_mission%NOTFOUND;
        UPDATE mission
           SET Fate = para_Fate
         WHERE CURRENT OF c_mission;
    END LOOP;
    CLOSE c_mission;

    DELETE FROM mission
     WHERE Speed_knots IS NULL
        OR Speed_knots < para_Speed_knots;

    SELECT AVG(Speed_knots)
      INTO v_avg_speed
      FROM mission;

    DELETE FROM mission
     WHERE Speed_knots < v_avg_speed;

    UPDATE mission
       SET Ship_ID = para_Ship_ID;
END sp;

